// Browser acceptance tests operate on SVG generated by the actual CLI.
const { chromium } = require('playwright');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { execFileSync } = require('node:child_process');

const root = path.resolve(__dirname, '../..');
const dir = path.join(root, '_build/browser');
fs.mkdirSync(dir, { recursive: true });
// Use Moon's public runner instead of depending on private _build layout.
// Toolchain releases may place native artifacts under different profiles.
const cli = ['moon', 'run', 'cmd/main', '--'];
function render(name, data, inverted = false) {
  const input = path.join(dir, name + '.folded');
  const output = path.join(dir, name + '.svg');
  fs.writeFileSync(input, data);
  execFileSync(cli[0], [...cli.slice(1), path.relative(root, input), '-o', path.relative(root, output), ...(inverted ? ['--inverted'] : [])], { cwd: root, stdio: ['ignore', 'ignore', 'pipe'] });
  return output;
}

(async () => {
  const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE || undefined });
  const page = await browser.newPage({ viewport: { width: 1600, height: 1000 }, deviceScaleFactor: 2 });
  const errors = [];
  page.on('pageerror', error => errors.push(String(error)));
  const open = async file => {
    await page.goto(pathToFileURL(file).href);
    await page.waitForFunction(() => typeof FRAMES !== 'undefined' && orig.length === FRAMES.length);
  };
  const search = async term => {
    await page.evaluate(term => { window.term = term; doSearch(); }, term);
    return page.locator('#matched').textContent();
  };
  for (const inverted of [false, true]) {
    await open(render('multiple-' + inverted, 'a 50\nb 50\n', inverted));
    assert.equal(await search('a|b'), 'Matched: 100%');
    assert.equal(await search('a'), 'Matched: 50.0%');
    assert.equal(await search('not-found'), 'Matched: 0.0%');
    assert.equal(await search('['), 'Invalid regular expression');
    assert.equal(await search('A'), 'Matched: 0.0%');
    await page.locator('#ignorecase').click();
    assert.equal(await page.locator('#matched').textContent(), 'Matched: 50.0%');
    await page.locator('#search').click(); // Reset search, then exercise the real prompt.
    page.once('dialog', dialog => dialog.accept('a|b'));
    await page.locator('#search').click();
    assert.equal(await page.locator('#matched').textContent(), 'Matched: 100%');

    await open(render('zoom-' + inverted, 'root;a;x 30\nroot;a;y 20\nroot;b 50', inverted));
    await page.locator('g[data-name="a"] rect').click();
    assert.equal(await page.locator('g[data-name="b"]').isVisible(), false);
    assert.equal(await search('b'), 'Matched: 0.0%');
    assert.equal(await search('root'), 'Matched: 0.0%'); // Ancestor is context, not coverage.
    assert.equal(await search('a|x|y'), 'Matched: 100%'); // Union, not sum.
    await page.locator('g[data-name="x"] rect').click();
    await page.locator('g[data-name="root"] rect').click();
    assert.equal(await page.locator('g[data-name="b"]').isVisible(), true);
    assert.equal(await page.locator('g[data-name="root"]').getAttribute('class'), '');
    assert.equal(await page.locator('#matched').textContent(), 'Matched: 50.0%');
    await page.locator('#unzoom').click();
    assert.equal(await page.locator('g.hide, g.parent').count(), 0);

    await open(render('narrow-' + inverted, 'r;wide 999\nr;long-function-name 1', inverted));
    const text = page.locator('g[data-name="long-function-name"] text');
    assert.equal(await text.count(), 1);
    assert.equal(await text.textContent(), '');
    await page.locator('g[data-name="long-function-name"] rect').click();
    assert.equal(await text.textContent(), 'long-function-name');
  }
  if (process.argv.includes('--update-examples')) {
    for (const [name, args] of [
      ['flame', ['testdata/demo.folded']],
      ['flame-diff', ['diff', 'testdata/demo-baseline.folded', 'testdata/demo.folded']],
    ]) {
      const output = path.join(root, 'examples', name + '.svg');
      execFileSync(cli[0], [...cli.slice(1), ...args, '-o', path.relative(root, output)], { cwd: root, stdio: ['ignore', 'ignore', 'pipe'] });
      await open(output);
      await page.mouse.move(1599, 999);
      await page.locator('svg').screenshot({ path: path.join(root, 'examples', name + '.png') });
    }
  }
  assert.deepEqual(errors, [], 'No JavaScript errors in generated SVG');
  await browser.close();
  console.log('SVG browser acceptance passed in both orientations.');
})().catch(error => { console.error(error); process.exit(1); });
